#!/usr/bin/env node
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {createRequire} from 'node:module';
import {fileURLToPath} from 'node:url';
import {captureBrowserEvidence,proposeBrowserMappings} from '../src/browser-evidence.js';
import {discover,execute} from '../src/execution.js';
import {plan} from '../src/selector.js';
import {digest} from '../src/provenance.js';
import {qualifyRoutingMappings} from '../src/mapping-qualification.js';
const write=(root,file,value)=>{fs.mkdirSync(path.dirname(path.join(root,file)),{recursive:true});fs.writeFileSync(path.join(root,file),typeof value==='string'?value:JSON.stringify(value,null,2));};
const fixtureModule=fileURLToPath(new URL('../src/browser-fixture.js',import.meta.url));
export function browserMappingProof({moduleRoot=process.cwd(),rawDirectory,channel=process.env.TESTLORE_BROWSER_CHANNEL,qualify=false}={}){
 if(channel!==undefined&&!['chrome','chromium'].includes(channel))throw new Error('Proof channel must be chrome or chromium');
 const rawFaults=[];
 const require=createRequire(path.join(moduleRoot,'package.json')),root=fs.mkdtempSync(path.join(os.tmpdir(),'testlore-browser-mapping-'));
 try{
  fs.mkdirSync(path.join(root,'node_modules/@playwright'),{recursive:true});for(const name of ['@playwright/test','playwright','playwright-core'])fs.symlinkSync(path.dirname(require.resolve(name+'/package.json')),path.join(root,'node_modules',name),'dir');
  write(root,'node_modules/testlore/package.json',{name:'testlore',type:'module',exports:{'./playwright':'./fixture.js'}});write(root,'node_modules/testlore/fixture.js',fs.readFileSync(fixtureModule,'utf8'));
  write(root,'node_modules/fixture-server/package.json',{name:'fixture-server',type:'module',exports:'./setup.js'});
  write(root,'node_modules/fixture-server/setup.js',`import http from 'node:http';import fs from 'node:fs';import path from 'node:path';export default async function(){const root=process.cwd();const server=http.createServer((req,res)=>{const name=decodeURIComponent(new URL(req.url,'http://localhost').pathname).slice(1);if(!/^[a-z.]+$/.test(name)){res.writeHead(404);res.end();return;}const file=path.join(root,'public',name);if(!fs.existsSync(file)){res.writeHead(404);res.end();return;}res.setHeader('content-type',name.endsWith('.html')?'text/html':name.endsWith('.css')?'text/css':name.endsWith('.js')?'application/javascript':'application/json');res.end(fs.readFileSync(file));});await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));process.env.FIXTURE_ORIGIN='http://127.0.0.1:'+server.address().port;fs.mkdirSync('.tddswarm',{recursive:true});fs.writeFileSync('.tddswarm/origin',process.env.FIXTURE_ORIGIN);return async()=>await new Promise(resolve=>server.close(resolve));}`);
  write(root,'package.json',{name:'browser-mapping-fixture',type:'module',private:true,dependencies:{'@playwright/test':'1.63.0',testlore:'0.1.0','fixture-server':'1.0.0'}});
  write(root,'playwright.config.mjs',`export default {testDir:'browser',globalSetup:'./globalSetup.mjs',workers:1,retries:0,timeout:5000,expect:{timeout:1000},projects:[{name:'chromium',use:${JSON.stringify({browserName:'chromium',...(channel?{channel}:{})})}}]};`);write(root,'globalSetup.mjs',`export {default} from 'fixture-server';`);
  const config={adapter:'playwright',discovery:'native',runner:[process.execPath,'node_modules/@playwright/test/cli.js','test','{files}']};write(root,'tddswarm.config.json',config);
  for(const route of ['landing','pricing']){
   write(root,`public/${route}.html`,`<link rel="stylesheet" href="/${route}.css"><h1>${route==='landing'?'Community tools':'Simple pricing'}</h1><p>ready</p><script src="/${route}.js"></script>`);
   write(root,`public/${route}.css`,'h1 { color: rgb(0, 128, 0); }');write(root,`source/${route}.js`,`document.querySelector('p').textContent='Working module';\n`);write(root,`public/${route}.js`,`document.querySelector('p').textContent='Working module';\n//# sourceMappingURL=${route}.js.map\n`);write(root,`public/${route}.js.map`,{version:3,file:`${route}.js`,sources:[`../source/${route}.js`],names:[],mappings:'AAAA'});
   write(root,`browser/${route}.spec.js`,`import {test as base,expect} from '@playwright/test';import {createBrowserTest} from 'testlore/playwright';const test=createBrowserTest(base);test('${route} heading style and module',async({page})=>{await page.goto(process.env.FIXTURE_ORIGIN+'/${route}.html');await expect(page.getByRole('heading')).toHaveText('${route==='landing'?'Community tools':'Simple pricing'}');await expect(page.getByRole('heading')).toHaveCSS('color','rgb(0, 128, 0)');await expect(page.locator('p')).toHaveText('Working module');});`);
  }
  const capture=captureBrowserEvidence(root,{timeoutMs:30000}),origin=fs.readFileSync(path.join(root,'.tddswarm/origin'),'utf8');
  if(!capture.complete)throw new Error(JSON.stringify({root,capture}));
  const proposal=proposeBrowserMappings(root,capture,{urlRoots:[{origin,urlPrefix:'/',directory:'public'}]});
  const landing=proposal.caseMappings.find(mapping=>mapping.file==='browser/landing.spec.js');const pricing=proposal.caseMappings.find(mapping=>mapping.file==='browser/pricing.spec.js');
  let qualification;
  if(qualify){
   const scenario={changed:['public/landing.html'],defects:[{path:'public/landing.html',content:'<h1>Wrong heading</h1>'}],timeoutMs:30000};
   const correct=qualifyRoutingMappings(root,proposal,scenario);
   const {integrity,...misroutedPayload}=structuredClone(proposal);
   misroutedPayload.proposed.browser.routes['/landing.html'].inputs=['public/pricing.html'];
   misroutedPayload.proposed.browser.routes['/pricing.html'].inputs.push('public/landing.html');
   const misrouted=qualifyRoutingMappings(root,{...misroutedPayload,integrity:digest(misroutedPayload)},scenario);
   const summarize=record=>({qualified:record.qualified,complete:record.complete,reasons:record.reasons,selected:record.selection?.selected,fullCases:record.full.tests.length,subsetCases:record.subset.tests.length,sameCase:record.full.tests.filter(test=>test.status==='failed').some(test=>record.subset.tests.some(other=>other.id===test.id&&other.status==='failed')),missedFailures:record.missedFailures.length,unexpectedFailures:record.unexpectedFailures.length,applied:record.applied,closedWorld:record.closedWorld,fallbackRequired:record.conservativeFallback.required});
   qualification={correct:summarize(correct),misrouted:summarize(misrouted)};
   rawFaults.push({name:'review-only-mapping-qualification',correct,misrouted});
  }
  let inventory;
  if(!qualify){write(root,'tddswarm.config.json',{...config,browser:{...proposal.proposed.browser,closedWorld:true}});inventory=discover(root,{...config,browser:{...proposal.proposed.browser,closedWorld:true}});}
  const faults=[];
  if(!qualify)for(const [name,file,mutant,changed]of [['heading','public/landing.html','<h1>Wrong heading</h1>',['public/landing.html']],['style','public/landing.css','h1 { color: rgb(255, 0, 0); }',['public/landing.css']],['module','public/landing.js',"document.querySelector('p').textContent='Broken module';\n//# sourceMappingURL=landing.js.map\n",['public/landing.js','source/landing.js']]]){
   const original=fs.readFileSync(path.join(root,file),'utf8');write(root,file,mutant);
   const selection=plan(root,{changed}),full=execute(root,inventory.files,{...config,browser:{...proposal.proposed.browser,closedWorld:true}},{capture:true,timeoutMs:30000}),subset=execute(root,selection.selected,{...config,browser:{...proposal.proposed.browser,closedWorld:true}},{capture:true,timeoutMs:30000});
   const failed=r=>r.tests.filter(test=>test.status==='failed');const caught=r=>r.complete&&r.exitCode!==0&&failed(r).length===1&&failed(r)[0].file==='browser/landing.spec.js'&&failed(r)[0].attempts.some(attempt=>attempt.errors.some(error=>/expect\(/.test(error.message||'')));
   rawFaults.push({name,full,subset,selection});
   faults.push({name,changed,mode:selection.mode,selected:selection.selected,total:selection.total,warnings:selection.warnings,fullCaught:caught(full),subsetCaught:caught(subset),sameCase:failed(full).length===1&&failed(subset).length===1&&failed(full)[0].id===failed(subset)[0].id,fullCases:full.tests.length,subsetCases:subset.tests.length});write(root,file,original);
  }
  const mapped=['public/landing.html','public/landing.css','public/landing.js','public/landing.js.map','source/landing.js'].every(file=>landing.dependencies.includes(file));
  const passed=(!qualify||(qualification.correct.qualified&&qualification.correct.sameCase&&!qualification.misrouted.qualified&&qualification.misrouted.missedFailures===1))&&capture.complete&&capture.observations.length===2&&capture.observations.every(observation=>observation.coverage.javascript.some(entry=>entry.ranges.length)&&observation.coverage.css.some(entry=>entry.ranges.length))&&mapped&&!landing.dependencies.some(file=>file.includes('pricing'))&&!pricing.dependencies.some(file=>file.includes('landing'))&&faults.every(fault=>fault.mode==='affected'&&fault.selected.length===1&&fault.fullCaught&&fault.subsetCaught&&fault.sameCase);
  const raw={capture,proposal,faults:rawFaults,fixture:Object.fromEntries(['public','source','browser'].flatMap(dir=>fs.readdirSync(path.join(root,dir)).sort().map(file=>[dir+'/'+file,fs.readFileSync(path.join(root,dir,file),'utf8')]))) };
  const redact=value=>typeof value==='string'?value.split(root).join('<fixture>').split(fs.realpathSync(root)).join('<fixture>').split(path.resolve(moduleRoot)).join('<tooling>').split(process.execPath).join('<node>').replace(/\/(?:private\/)?var\/folders\/[^\s:'\"\n]+\/T\/(?:tddswarm|testlore)-[^/\s:'\"\n]+/g,'<scratch>').replace(/\/(?:private\/)?tmp\/(?:tddswarm|testlore)-[^/\s:'\"\n]+/g,'<scratch>').replace(/http:\/\/127\.0\.0\.1:\d+/g,'http://127.0.0.1:<port>'):Array.isArray(value)?value.map(redact):value&&typeof value==='object'?Object.fromEntries(Object.entries(value).map(([key,item])=>[key,redact(item)])):value;
  const rawArtifacts=[];if(rawDirectory){fs.mkdirSync(rawDirectory,{recursive:true});for(const [name,value]of Object.entries(raw)){const text=JSON.stringify(redact(value),null,2)+'\n',file=name+'.json';fs.writeFileSync(path.join(rawDirectory,file),text);rawArtifacts.push({file,sha256:digest(text)});}}
  return {schemaVersion:1,scope:'Controlled real Chromium two-route mapping proof',passed,browser:{channel:channel||'bundled-headless-shell',versions:[...new Set(capture.observations.map(observation=>observation.browserVersion))]},library:{name:'@playwright/test',version:JSON.parse(fs.readFileSync(require.resolve('@playwright/test/package.json'))).version},capture:{complete:capture.complete,cases:capture.observations.length,routes:capture.observations.map(observation=>({file:observation.file,routes:observation.routes.map(raw=>new URL(raw).pathname),javascriptEntries:observation.coverage.javascript.length,cssEntries:observation.coverage.css.length})),warnings:capture.warnings},proposal:{observationsComplete:proposal.observationsComplete,closedWorld:proposal.closedWorld,reviewRequired:proposal.reviewRequired,mappedSources:proposal.caseMappings.map(({file,dependencies})=>({file,dependencies})),warnings:proposal.warnings},faults,...(qualification?{qualification}:{}),rawArtifacts,fixtureHash:digest([...fs.readdirSync(path.join(root,'public')).sort()].map(file=>[file,fs.readFileSync(path.join(root,'public',file),'utf8')])),limitations:[qualify?'Manually authored fixture and one fixed heading defect plus a misrouted mapping; no broad recall or wall-clock speed claim.':'Manually authored fixture and three fixed defects; no broad recall or wall-clock speed claim.','URL-to-directory authority is explicit; source maps are local tracked files, not remote downloads.',qualify?'Review-only qualification used isolated candidate configurations; mappings were never applied to the observed fixture.':'Mappings were applied only in this manually scoped fixture with an explicit browser.closedWorld:true assertion after review simulation; auto proposals remain closedWorld:false.','Observed requests and executed coverage do not make dependency declarations complete.']};
 }finally{fs.rmSync(root,{recursive:true,force:true});}
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){try{let output,rawDirectory,channel,qualify=false;for(let i=2;i<process.argv.length;i++){const option=process.argv[i];if(option==='--qualify'){qualify=true;continue;}if(!['--output','--raw-directory','--channel'].includes(option)||!process.argv[++i])throw new Error('Usage: node scripts/browser-mapping-proof.js [--channel chrome|chromium] [--qualify] [--output FILE] [--raw-directory DIR]');if(option==='--output')output=process.argv[i];else if(option==='--raw-directory')rawDirectory=process.argv[i];else channel=process.argv[i];}const record=browserMappingProof({rawDirectory,channel,qualify}),text=JSON.stringify(record,null,2)+'\n';if(output){fs.mkdirSync(path.dirname(path.resolve(output)),{recursive:true});fs.writeFileSync(output,text);}process.stdout.write(text);process.exitCode=record.passed?0:1;}catch(error){process.stderr.write(error.stack+'\n');process.exitCode=1;}}
